using Payments;

namespace PaymentGateway.Tests;

[TestClass]
public class PaymentGatewayTests
{
    private Payments.PaymentGateway _gateway = null!;

    [TestInitialize]
    public void Setup()
    {
        _gateway = new Payments.PaymentGateway();
    }

    #region ChargeAsync Tests

    [TestMethod]
    [DataRow("tok_valid_visa", 10.00)]
    [DataRow("tok_valid_mastercard", 99.99)]
    [DataRow("tok_valid_amex", 1.00)]
    public async Task ChargeAsync_ValidTokenAndAmount_ReturnsSuccessWithChargeId(string token, double amount)
    {
        var result = await _gateway.ChargeAsync(token, (decimal)amount);

        Assert.IsTrue(result.Success);
        Assert.IsFalse(string.IsNullOrWhiteSpace(result.ChargeId));
    }

    [TestMethod]
    [DataRow(0.00)]
    [DataRow(-5.00)]
    [DataRow(-0.01)]
    public async Task ChargeAsync_InvalidAmount_ReturnsFailureOrThrows(double amount)
    {
        await Assert.ThrowsExceptionAsync<ArgumentException>(
            () => _gateway.ChargeAsync("tok_valid", (decimal)amount));
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public async Task ChargeAsync_InvalidToken_ThrowsArgumentException(string? token)
    {
        await Assert.ThrowsExceptionAsync<ArgumentException>(
            () => _gateway.ChargeAsync(token!, 50.00m));
    }

    [TestMethod]
    public async Task ChargeAsync_DeclinedCard_ReturnsFailure()
    {
        var result = await _gateway.ChargeAsync("tok_declined", 25.00m);

        Assert.IsFalse(result.Success);
        Assert.IsFalse(string.IsNullOrWhiteSpace(result.ChargeId));
    }

    [TestMethod]
    public async Task ChargeAsync_VeryLargeAmount_HandlesCorrectly()
    {
        // Boundary: very large charge amount
        var result = await _gateway.ChargeAsync("tok_valid", 999_999.99m);

        Assert.IsNotNull(result);
    }

    #endregion

    #region RefundAsync Tests

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ReturnsSuccessWithRefundId()
    {
        var result = await _gateway.RefundAsync("ch_valid_123");

        Assert.IsTrue(result.Success);
        Assert.IsFalse(string.IsNullOrWhiteSpace(result.RefundId));
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public async Task RefundAsync_InvalidChargeId_ThrowsArgumentException(string? chargeId)
    {
        await Assert.ThrowsExceptionAsync<ArgumentException>(
            () => _gateway.RefundAsync(chargeId!));
    }

    [TestMethod]
    public async Task RefundAsync_NonExistentChargeId_ReturnsFailure()
    {
        var result = await _gateway.RefundAsync("ch_does_not_exist");

        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    public async Task RefundAsync_AlreadyRefundedCharge_ReturnsFailure()
    {
        // First refund succeeds
        await _gateway.RefundAsync("ch_already_refunded");

        // Second refund on same charge should fail
        var result = await _gateway.RefundAsync("ch_already_refunded");

        Assert.IsFalse(result.Success);
    }

    #endregion

    #region ChargeResult and RefundResult Record Tests

    [TestMethod]
    public void ChargeResult_Properties_AreAccessible()
    {
        var result = new ChargeResult("ch_abc", true);

        Assert.AreEqual("ch_abc", result.ChargeId);
        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public void RefundResult_Properties_AreAccessible()
    {
        var result = new RefundResult("re_xyz", false);

        Assert.AreEqual("re_xyz", result.RefundId);
        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    public void ChargeResult_Equality_WorksCorrectly()
    {
        var a = new ChargeResult("ch_1", true);
        var b = new ChargeResult("ch_1", true);
        var c = new ChargeResult("ch_2", true);

        Assert.AreEqual(a, b);
        Assert.AreNotEqual(a, c);
    }

    #endregion
}

